function sortRecords(records) {
  function mergeSort(items) {
    if (items.length <= 1) return items;
    const middle = Math.floor(items.length / 2);
    const left = mergeSort(items.slice(0, middle));
    const right = mergeSort(items.slice(middle));
    const merged = [];
    let leftIndex = 0;
    let rightIndex = 0;
    while (leftIndex < left.length && rightIndex < right.length) {
      const leftItem = left[leftIndex];
      const rightItem = right[rightIndex];
      const leftFirst =
        leftItem.score > rightItem.score ||
        (leftItem.score === rightItem.score && leftItem.name <= rightItem.name);
      if (leftFirst) {
        merged.push(leftItem);
        leftIndex += 1;
      } else {
        merged.push(rightItem);
        rightIndex += 1;
      }
    }
    while (leftIndex < left.length) {
      merged.push(left[leftIndex]);
      leftIndex += 1;
    }
    while (rightIndex < right.length) {
      merged.push(right[rightIndex]);
      rightIndex += 1;
    }
    return merged;
  }
  return mergeSort(records);
}
